# Rust ANI binding library: the only entry consumed by the ANI runtime is
# ANI_Constructor (generated by ani_constructor!, #[no_mangle]).
# cxxbridge trampolines and the statically linked ani_rs/cxx deps are
# all intra-DSO.
{
  global:
    ANI_Constructor;
  local:
    *;
};
